def parse_area(value):
    text = clean(value)
    if not text:
        return None
    total = text.split('/')[0].strip().replace(',', '.')
    if re.fullmatch(r'[0-9]+(?:\.[0-9]+)?', total) is None:
        return None
    return Decimal(total)
assert parse_area('8abc/4') is None
assert parse_area('51,2/30/8') == Decimal('51.2')
assert parse_area('2026-11-03') is None
parsed = [{'salary': parse_salary(row['salary']), 'area_m2': parse_area(row['area'])} for row in rows]
for row in parsed:
